func skipValue(dec *json.Decoder) error {
	tok, err := nextToken(dec)
	if err != nil {
		return err
	}
	return skipRest(dec, tok)
}

func skipRest(dec *json.Decoder, tok json.Token) error {
	delim, ok := tok.(json.Delim)
	if !ok {
		return nil
	}
	var closer json.Delim
	switch delim {
	case '{':
		closer = '}'
		for dec.More() {
			if _, err := objectKey(dec); err != nil {
				return err
			}
			if err := skipValue(dec); err != nil {
				return err
			}
		}
	case '[':
		closer = ']'
		for dec.More() {
			if err := skipValue(dec); err != nil {
				return err
			}
		}
	default:
		return errAbortScan
	}
	tok, err := nextToken(dec)
	if err != nil {
		return err
	}
	if d, ok := tok.(json.Delim); !ok || d != closer {
		return errAbortScan
	}
	return nil
}
